//! Generated original Zombiebox shambler meshes. Y up, +Z forward.
//! Part coordinates are normalized for the rigid-part transforms in `animation.rs`.
use super::{GeometryTag, MaterialFlags, MeshBuffer, MeshBuilder, VertexMeta, WorldVertex};
use glam::Vec3;

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum ZombieMeshPart {
    Body,
    Head,
    ArmL,
    ArmR,
    LegL,
    LegR,
}

pub fn zombie_mesh(part: ZombieMeshPart) -> MeshBuffer {
    let triangles = match part {
        ZombieMeshPart::Body => BODY,
        ZombieMeshPart::Head => HEAD,
        ZombieMeshPart::LegL => LEGL,
        ZombieMeshPart::LegR => LEGR,
        ZombieMeshPart::ArmL => ARML,
        ZombieMeshPart::ArmR => ARMR,
    };
    let meta = VertexMeta::DEFAULT
        .with_tag(GeometryTag::Actor)
        .with_flags(MaterialFlags::ACTOR_MIN_LIGHT | MaterialFlags::CUTAWAY_EXEMPT);
    let mut b = MeshBuilder::new();
    for &(points, color) in triangles {
        let [a, c, d] = points.map(Vec3::from_array);
        b.push_triangle(
            a,
            c,
            d,
            WorldVertex::rgba8(color[0], color[1], color[2], 255),
            meta,
        );
    }
    b.build()
}

